// Lektionen 19–24 (Offenbarungsreihenfolge, Kairoer Chronologie)
window.LEKTIONEN4 = [
// ───────────────────────── Lektion 19: Al-Fīl ─────────────────────────
{
sure: 105, offb: 19, name: "Al-Fīl", arab: "سُورَةُ الْفِيلِ", de: "Der Elefant", verse: 5, ort: "Mekka",
zeit: "Frühmekkanisch – erinnert an das „Jahr des Elefanten“ (ca. 570 n. Chr.), das Geburtsjahr des Propheten ﷺ",
kurz: "Rund 40 Jahre vor dieser Offenbarung geschah vor den Toren Mekkas etwas, das jeder Zuhörer noch von Augenzeugen kannte: Abraha, der christliche Herrscher des Jemen, zog mit einem Heer und Kriegselefanten heran, um die Kaaba zu zerstören – damit die Pilger künftig zu seiner Prachtkirche in Sanaa kämen. Die Mekkaner konnten nichts ausrichten. Doch der Leitelefant weigerte sich, auf Mekka zuzugehen, und Allah sandte Vogelschwärme mit Steinen aus gebranntem Ton: Das Heer wurde „wie abgefressenes Stroh“. Die Sure stellt den Quraisch die Frage: Habt ihr nicht gesehen, wie dein Herr mit den Leuten des Elefanten verfuhr? – Der Gott, der Sein Haus gegen Abraha schützte, ist derselbe, dessen Gesandten ihr jetzt bekämpft.",
schluessel: {arab: "أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ", ueb: "Siehst du nicht, wie dein Herr mit den Leuten des Elefanten verfuhr?", ref: "105:1"},
kontext: ["Historischer Hintergrund: Abraha al-Aschram regierte den Jemen für das christliche Aksum (Äthiopien). Er baute in Sanaa die Kathedrale al-Qullais und wollte den arabischen Pilgerverkehr von Mekka dorthin umlenken. Als das misslang (ein Araber hatte die Kirche entehrt), schwor er, die Kaaba abzureißen, und marschierte mit einem Heer samt Elefant(en) nach Norden – für Arabien eine nie gesehene Militärtechnologie.",
"Vor Mekka beschlagnahmte Abrahas Heer Kamele, darunter zweihundert des ʿAbd al-Muṭṭalib, des Großvaters des Propheten ﷺ. Dessen überlieferte Antwort wurde sprichwörtlich: Er verhandelte nur über seine Kamele, und als Abraha sich wunderte, sagte er: „Ich bin der Herr der Kamele – das Haus hat seinen eigenen Herrn, Der es schützen wird.“ Die Mekkaner zogen sich in die Berge zurück; eingreifen konnten sie nicht. Dann kam, was die Sure beschreibt: Vogelschwärme (abābīl) mit Steinen aus sidschdschīl – das Heer brach zusammen, Abraha starb auf dem Rückzug elend.",
"Warum diese Sure jetzt, 40 Jahre später? Die Quraisch verdankten diesem Ereignis ihr Prestige („Leute des Hauses Allahs“) und ihre Sicherheit – und verfolgten gleichzeitig den Gesandten eben dieses Gottes. Die Sure zieht ihnen den Boden unter der Selbstgerechtigkeit weg: Nicht ihr habt die Kaaba verteidigt – Allah hat es getan, ohne euch. Und im Geburtsjahr des Propheten ﷺ: Die Gelehrten sehen darin eine Vorbereitung (irhāṣ) seiner Sendung."],
asbab: ["Die Sure hat keinen aktuellen Anlass im engeren Sinn – sie erinnert an das allgemein bekannte Elefanten-Ereignis (ca. 570 n. Chr.), das durch die mekkanische Erinnerung und die Sīra-Werke (Ibn Isḥāq/Ibn Hischām) breit bezeugt ist; der Koran selbst ist hier die gesichertste Quelle des Geschehens."],
begriffe: [
 {arab: "أَصْحَاب الْفِيل", tr: "aṣḥāb al-fīl", wurzel: "f-y-l", erkl: "„Die Leute des Elefanten“ – Abrahas Heer. Die Araber datierten fortan nach diesem Jahr: ʿĀm al-Fīl, das Jahr des Elefanten – das Geburtsjahr des Propheten ﷺ."},
 {arab: "كَيْد", tr: "kaid", wurzel: "k-y-d", erkl: "List/Plan – „Hat Er ihre List nicht ins Leere laufen lassen (fī taḍlīl)?“ Abrahas Plan war durchdacht: Kirche bauen, Pilger umlenken, Konkurrenz zerstören. Gegen Allahs Plan zerfiel er zu Stroh – ein Muster, das der Koran oft zeigt (vgl. 8:30)."},
 {arab: "أَبَابِيل", tr: "abābīl", wurzel: "–", erkl: "„In Schwärmen / Schar auf Schar“ – kein Vogelname, sondern die Beschreibung: Schwärme über Schwärme. Das Wort kommt nur hier im Koran vor."},
 {arab: "سِجِّيل", tr: "sidschdschīl", wurzel: "s-dsch-l (Lehnwort)", erkl: "Steine aus gebranntem Ton – dasselbe Material nennt der Koran bei der Strafe über das Volk Lūts (11:82). Kleinste Mittel, größte Wirkung: Allah braucht keine Gegenarmee."},
 {arab: "عَصْف مَأْكُول", tr: "ʿaṣf maʾkūl", wurzel: "ʿ-ṣ-f / ʾ-k-l", erkl: "„Abgefressenes Stroh/Blattwerk“ – wie ein Feld, das das Vieh kahlgefressen und zertrampelt hat. Das Schlussbild der Sure: Militärmacht, reduziert auf Häcksel."}
],
tafsir: [
 {vers: "Vers 1–2", text: "„Siehst du nicht, wie dein Herr mit den Leuten des Elefanten verfuhr? Hat Er ihre List nicht ins Leere laufen lassen?“ – „Siehst du nicht“ (a-lam tara) an Zuhörer, die das Jahr des Elefanten teils noch erlebt hatten: Der Koran argumentiert hier mit einem öffentlich bekannten, unbestrittenen Faktum – niemand in Mekka widersprach dieser Sure. Ibn Kathīr: Allah ließ die Kaaba durch ein Nicht-Heer verteidigen, damit die Ehre niemandem außer Ihm zufällt – ausdrücklich auch nicht den Quraisch, die sich auf die Berge zurückgezogen hatten."},
 {vers: "Verse 3–5", text: "„Und Er sandte gegen sie Vögel in Schwärmen, die sie mit Steinen aus gebranntem Ton bewarfen, und machte sie wie abgefressenes Stroh.“ – As-Saʿdī: Beachte das Gefälle der Mittel – Elefanten (größtes Landtier, Militärtechnologie) gegen Vögel mit Tonsteinchen; Allah demütigt die Macht durch das Kleine, wie Er Pharao durch Heuschrecken und Läuse prüfte (7:133). Al-Qurṭubī verweist auf den Zusammenhang mit der Folgesure Quraisch (106): WEIL Allah das Haus schützte, „sollen sie dem Herrn dieses Hauses dienen, Der sie gegen Hunger gespeist und vor Furcht gesichert hat“ – Sicherheit und Wohlstand sind Leihgaben mit Verwendungszweck. Und eine Grenze, die der Prophet ﷺ selbst zog: Am Tag der Eroberung Mekkas sagte er, Allah habe den Elefanten von Mekka zurückgehalten, aber Ihm, dem Gesandten, sei (das Kämpfen dort) nur eine Stunde eines Tages erlaubt worden – die Heiligkeit der Stadt gilt fort (Sahih al-Buchari, Nr. 104; Sahih Muslim, Nr. 1354)."}
],
ahadith: [
 {text: "„Allah hat den Elefanten von Mekka zurückgehalten und hat Seinen Gesandten und die Gläubigen über sie (die Stadt) verfügen lassen; sie wurde mir nur für eine Stunde eines Tages erlaubt, und ihre Heiligkeit ist heute wieder wie gestern.“ – aus der Predigt bei der Eroberung Mekkas.", quelle: "Sahih al-Buchari, Nr. 104; Sahih Muslim, Nr. 1354"},
 {text: "Am Tag von Ḥudaibiya legte sich das Kamel des Propheten ﷺ nieder; die Leute sagten, es sei störrisch. Er sagte: „… Zurückgehalten hat es Der, Der den Elefanten zurückhielt“ – und schwor, jedem Friedensvorschlag der Quraisch zuzustimmen, der die Heiligtümer ehrt.", quelle: "Sahih al-Buchari, Nr. 2731 (langer Ḥudaibiya-Bericht)"},
 {text: "„Dieses (Mekka) ist eine Stadt, die Allah geheiligt hat am Tag, da Er Himmel und Erde erschuf; sie ist heilig durch Allahs Heiligung bis zum Tag der Auferstehung.“", quelle: "Sahih al-Buchari, Nr. 3189; Sahih Muslim, Nr. 1353"}
],
hanafi: null,
umsetzung: [
 "Lerne das Muster: Wenn eine Übermacht gegen den Dīn steht (medial, politisch, persönlich), erinnere dich an ʿAbd al-Muṭṭalibs Satz – „Das Haus hat seinen Herrn.“ Tu deinen Teil (er verhandelte um seine Kamele!) und überlass Allah Seinen.",
 "Hüte dich vor dem Quraisch-Fehler: von Allahs Schutz und Gaben leben und gleichzeitig gegen Seine Sache arbeiten. Prüfe: Wo profitierst du vom Dīn (Gemeinschaft, Ruf, Herkunft), ohne ihm zu dienen?",
 "Nimm die Verbindung 105→106 in dein Dankgebet: Sicherheit und Versorgung sind die zwei Grundgaben (vgl. at-Tirmidhī, Nr. 2346 aus Lektion 16) – und ihr ‚Verwendungszweck' ist ʿIbāda.",
 "Erzähl die Elefanten-Geschichte deinen Kindern/Geschwistern – sie ist die kindgerechteste Einstiegssure: spannend, historisch, mit klarer Pointe."
]
},

// ───────────────────────── Lektion 20: Al-Falaq ─────────────────────────
{
sure: 113, offb: 20, name: "Al-Falaq", arab: "سُورَةُ الْفَلَقِ", de: "Das Frühlicht", verse: 5, ort: "Mekka",
zeit: "Mekkanisch (nach anderen medinensisch) – erste der beiden Schutzsuren (al-muʿawwidhatān)",
kurz: "Die erste der beiden Schutzsuren, über die der Prophet ﷺ sagte: „Diese Nacht sind Verse herabgesandt worden, dergleichen nie gesehen wurden.“ Al-Falaq ist die Zuflucht vor dem Übel von AUSSEN – in vier Kreisen: das Übel alles Erschaffenen, die Finsternis der Nacht, die Knotenbläserinnen (Zauberei) und der Neider, wenn er neidet. Der Schlüssel liegt im ersten Wort: Zuflucht nicht bei Talismanen, Steinen oder Sprüchen – wie die Araber es taten – sondern beim „Herrn des Frühlichts“: Der die Dunkelheit jeden Morgen aufspaltet, kann jedes Dunkel aufspalten, das dich bedroht. Der Prophet ﷺ rezitierte beide Schutzsuren jeden Abend, jeden Morgen und vor dem Schlafen – sie sind das Sicherheitssystem des Muslims.",
schluessel: {arab: "قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ", ueb: "Sag: Ich nehme Zuflucht beim Herrn des Frühlichts.", ref: "113:1"},
kontext: ["Die vorislamischen Araber lebten in ständiger Angst vor unsichtbaren Mächten: Sie hängten Amulette um, suchten Schutz bei Dschinn („Herr dieses Tals…“, vgl. 72:6) und fürchteten Zauberei und den bösen Blick. Die beiden Schutzsuren ersetzen dieses ganze Angstsystem durch einen einzigen Satz: aʿūdhu bi-rabbi… – Zuflucht beim Herrn. Nicht die Angst wird geleugnet (das Übel ist real), sondern die Adresse wird korrigiert.",
"ʿUqba ibn ʿĀmir berichtet, dass der Prophet ﷺ ihm sagte: „Siehst du nicht die Verse, die diese Nacht herabgesandt wurden, dergleichen nie gesehen wurden? ‚Sag: Ich nehme Zuflucht beim Herrn des Frühlichts' und ‚Sag: Ich nehme Zuflucht beim Herrn der Menschen'“ (Sahih Muslim, Nr. 814).",
"In Medina wurde der Prophet ﷺ von Labīd ibn al-Aʿṣam verzaubert (siḥr) – eine Zeit der Beeinträchtigung, bis Allah ihm im Traum die Sache zeigte und der Zauber (ein Kamm mit Haaren, in einem Brunnen) unschädlich gemacht wurde (Sahih al-Buchari, Nr. 5763; Sahih Muslim, Nr. 2189). Manche Überlieferungen verbinden die Schutzsuren mit diesem Ereignis; gesichert ist: Sie sind die prophetische Antwort auf genau diese Art von Übel – und ʿĀʾischa berichtet, dass er in seiner letzten Krankheit mit ihnen über sich blies."],
asbab: [
 {text: "ʿUqba ibn ʿĀmir: Die Herabsendung der beiden Schutzsuren als Verse, „dergleichen nie gesehen wurden“.", quelle: "Sahih Muslim, Nr. 814"},
 {text: "Der Siḥr des Labīd ibn al-Aʿṣam gegen den Propheten ﷺ und seine Aufdeckung – von manchen als Anlass bzw. Anwendungsfall der Schutzsuren überliefert (die Verknüpfung mit der Herabsendung ist nicht sahih gesichert; der Vorfall selbst ist es).", quelle: "Sahih al-Buchari, Nr. 5763; Sahih Muslim, Nr. 2189"}
],
begriffe: [
 {arab: "أَعُوذُ", tr: "aʿūdhu", wurzel: "ʿ-w-dh", erkl: "„Ich nehme Zuflucht / flüchte mich“ – wie ein Kind hinter den Vater. Istiʿādha ist ʿIbāda: Sie bei jemand anderem als Allah zu suchen (Amulette, Dschinn, ‚Energien') ist Schirk; bei Allah ist sie Tauhīd in Aktion."},
 {arab: "الْفَلَق", tr: "al-falaq", wurzel: "f-l-q", erkl: "Das Frühlicht/der Tagesanbruch – wörtlich „das Aufgespaltene“: Allah „spaltet“ die Nacht mit dem Morgen (6:96: fāliq al-iṣbāḥ) und das Samenkorn mit dem Keim (6:95). Die Botschaft im Namen: Jede Dunkelheit hat ein Aufbrechen."},
 {arab: "غَاسِق إِذَا وَقَبَ", tr: "ġāsiq idhā waqab", wurzel: "ġ-s-q / w-q-b", erkl: "„Die Dunkelheit, wenn sie hereinbricht“ – die Nacht als Zeit, in der Raubtiere, Verbrechen und Ängste aktiv werden. Realistische Gefahrenkunde, kein Aberglaube: Das meiste Übel liebt die Deckung."},
 {arab: "النَّفَّاثَات فِي الْعُقَد", tr: "an-naffāthāt fī l-ʿuqad", wurzel: "n-f-th / ʿ-q-d", erkl: "„Die auf die Knoten Blasenden“ – Zauberinnen/Zauberer, die Knoten knüpften und besprachen. Der Koran bestätigt, dass Siḥr real schaden kann (vgl. 2:102: „… doch sie schaden niemandem damit, außer mit Allahs Erlaubnis“) – und entmachtet ihn zugleich: Zuflucht beim Herrn genügt."},
 {arab: "حَاسِد إِذَا حَسَدَ", tr: "ḥāsid idhā ḥasad", wurzel: "ḥ-s-d", erkl: "„Der Neider, wenn er neidet“ – ḥasad: wünschen, dass dem anderen die Gabe genommen wird. Die Sure endet beim alltäglichsten Übel: Der böse Blick (ʿain) ist nach dem Hadith wahr (Sahih Muslim, Nr. 2188). Beachte: „wenn er neidet“ – der stille Neid im Herzen, der nicht handelt, ist nicht jedermanns Übel."}
],
tafsir: [
 {vers: "Verse 1–2", text: "„Sag: Ich nehme Zuflucht beim Herrn des Frühlichts vor dem Übel dessen, was Er erschaffen hat.“ – Der weiteste Schutzkreis zuerst: alles Erschaffene, soweit darin Übel liegt. Ibn Kathīr: Das Übel liegt nicht in der Schöpfung als solcher (Allah erschafft alles mit Weisheit), sondern in dem, was Geschöpfe anrichten. Wer beim Herrn ALLER Geschöpfe Zuflucht nimmt, hat keinen Feind mehr, der außerhalb der Zuständigkeit läge – das ist die Logik, die Amulette überflüssig macht."},
 {vers: "Verse 3–5", text: "Drei konkrete Kreise: Nacht, Zauberei, Neid. As-Saʿdī: Die Auswahl deckt die drei Einfallstore des äußeren Übels – das Unsichtbare/Situative (Dunkelheit), das gezielt Böse (Siḥr) und das sozial Alltägliche (Ḥasad). Zum Neid sagt al-Qurṭubī: Er ist die älteste Sünde (Iblīs gegen Ādam, Qābīl gegen Hābīl) – und die Sure lehrt den Umgang auf der Opferseite: nicht Gegenneid, nicht Panik, sondern Zuflucht und weitergehen. Zur praktischen Anwendung gehört die Sunna: morgens und abends dreimal al-Ichlāṣ, al-Falaq und an-Nās – „das genügt dir gegen alles“ (Sunan Abū Dāwūd, Nr. 5082; at-Tirmidhī, Nr. 3575, hasan sahih); vor dem Schlafen in die Hände blasen, rezitieren, über den Körper streichen (Sahih al-Buchari, Nr. 5017); und bei Krankheit als Ruqya (Sahih al-Buchari, Nr. 5735)."}
],
ahadith: [
 {text: "ʿUqba ibn ʿĀmir: „Siehst du nicht die Verse, die diese Nacht herabgesandt wurden, dergleichen nie gesehen wurden? …“ – über die beiden Schutzsuren.", quelle: "Sahih Muslim, Nr. 814"},
 {text: "ʿĀʾischa: Der Prophet ﷺ blies jede Nacht vor dem Schlafen in seine Hände, rezitierte al-Ichlāṣ, al-Falaq und an-Nās und strich damit über seinen Körper, beginnend mit Kopf und Gesicht – dreimal; in seiner letzten Krankheit tat sie es für ihn.", quelle: "Sahih al-Buchari, Nr. 5017 (vgl. 5735)"},
 {text: "„Der böse Blick (al-ʿain) ist wahr; und wäre etwas dem Vorherbestimmten zuvorgekommen, dann der böse Blick.“", quelle: "Sahih Muslim, Nr. 2188"}
],
hanafi: "Zur Einordnung von Ruqya und Schutz: Erlaubt (und Sunna) ist der Schutz durch Koran, überlieferte Bittgebete und das Vertrauen auf Allah; verboten sind nach allen Schulen – hanafitisch klar ausformuliert – Amulette mit unverständlichen Formeln, Wahrsagerei und das Aufsuchen von ‚Heilern', die mit Dschinn arbeiten („Wer einen Wahrsager aufsucht und ihm glaubt, der hat den Unglauben begangen gegenüber dem, was auf Muhammad herabgesandt wurde“ – Abū Dāwūd, Nr. 3904, sahih). Praktische hanafitische Linie: Erst die Sunna-Mittel (Adhkār, Schutzsuren, Gebet), bei Krankheit zusätzlich Medizin – beides widerspricht sich nicht.",
umsetzung: [
 "Installiere das prophetische Sicherheitssystem: dreimal al-Ichlāṣ + al-Falaq + an-Nās nach Fadschr und nach Maghrib/vor dem Schlafen – keine zwei Minuten, und du folgst wörtlich der Sunna.",
 "Entrümple Ersatz-Zuflüchte: Nazar-Amulette, ‚Glücksbringer', abergläubische Rituale – die Sure ersetzt sie alle durch rabb al-falaq. (Das blaue Auge schützt nicht – es widerspricht dem ersten Vers.)",
 "Gegen eigenen Neid (die Täterseite!): Wenn du bei jemandem eine Gabe siehst, sprich bārakallāhu lahu (möge Allah sie ihm segnen) und bitte Allah für dich um Seine Gunst – Neid stirbt, wo Segenswunsch gesprochen wird.",
 "Nimm die falaq-Hoffnung wörtlich: In deiner dunkelsten Phase bete zu Dem, Der den Morgen aus der Nacht spaltet – Er spaltet auch Sorgen auf. Kombiniere mit 94:5–6 aus Lektion 12."
]
},

// ───────────────────────── Lektion 21: An-Nās ─────────────────────────
{
sure: 114, offb: 21, name: "An-Nās", arab: "سُورَةُ النَّاسِ", de: "Die Menschen", verse: 6, ort: "Mekka",
zeit: "Mekkanisch (nach anderen medinensisch) – zweite Schutzsure und Schlusssure des Korans",
kurz: "Die zweite Schutzsure – und das letzte Wort des Mushaf. Al-Falaq schützte vor dem Übel von außen; An-Nās schützt vor dem gefährlicheren Übel von INNEN: dem Einflüsterer (waswās), der sich zurückzieht, sobald Allahs gedacht wird (channās), und „in die Brüste der Menschen einflüstert – von den Dschinn und den Menschen“. Gegen diesen unsichtbaren Dauerangreifer ruft die Sure Allah mit drei Titeln an, die genau die Schwachstelle abdecken: Herr der Menschen (Er erzieht dich), König der Menschen (Er befiehlt über dich), Gott der Menschen (Er allein wird angebetet). Dass der Koran mit dem Schutz des Herzens vor der Einflüsterung ENDET, ist selbst Tafsir: Die letzte Schlacht jedes Lebens findet innen statt.",
schluessel: {arab: "الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۝ مِنَ الْجِنَّةِ وَالنَّاسِ", ueb: "… der in die Brüste der Menschen einflüstert – von den Dschinn und den Menschen.", ref: "114:5–6"},
kontext: ["Die beiden Schutzsuren sind ein Paar mit Systematik: Al-Falaq nennt VIER äußere Übel und EINEN Gottestitel (Herr des Frühlichts); An-Nās nennt EIN inneres Übel und DREI Gottestitel. Die Gelehrten lesen daraus: Das innere Übel ist gefährlicher und braucht stärkeren Schutz – ein äußerer Feind kann dein Leben nehmen, der innere dein Jenseits.",
"Waswasa ist lautmalerisch: das Wispern, Rascheln, der Gedanke, der sich einschleicht – Zweifel am Dīn, Antrieb zur Sünde, Skrupel im Gebet, Angstspiralen. Der Koran nimmt diese Innenwelt ernst: Schaitan arbeitet nicht mit Gewalt, sondern mit Vorschlägen (14:22: „Ich hatte keine Macht über euch, außer dass ich euch rief und ihr mir folgtet“).",
"Wichtig: „von den Dschinn und den Menschen“ – auch Menschen können waswās sein: die Stimme, die dich vom Gebet abbringt, die zur Sünde schönredet, die Zweifel sät. Der Prophet ﷺ lehrte den Umgang: Wer Einflüsterungen über Allah spürt („Wer hat Allah erschaffen?“), der nehme Zuflucht bei Allah und höre auf (damit, dem Gedanken zu folgen) – Sahih al-Buchari, Nr. 3276; und: solche Anfechtung zu HASSEN ist selbst „klarer Glaube“ (Sahih Muslim, Nr. 132)."],
asbab: [
 {text: "Wie Al-Falaq: Herabsendung der beiden Schutzsuren gemeinsam bezeugt durch ʿUqba ibn ʿĀmir.", quelle: "Sahih Muslim, Nr. 814"}
],
begriffe: [
 {arab: "رَبّ / مَلِك / إِلَٰه", tr: "rabb / malik / ilāh", wurzel: "r-b-b / m-l-k / ʾ-l-h", erkl: "Drei Titel in Steigerung: der Herr (Erzieher/Versorger), der König (Herrscher mit Befehlsgewalt), der Gott (der allein Angebetete). Gegen den Einflüsterer brauchst du alle drei: Seine Fürsorge, Seine Macht, Seine Alleinstellung in deinem Herzen."},
 {arab: "الْوَسْوَاس", tr: "al-waswās", wurzel: "w-s-w-s", erkl: "Der Einflüsterer – Intensivform: der, dessen Wesen das Flüstern ist. Gemeint ist Schaitan und jede Quelle böser Eingebungen. Die Waffe ist der Gedanke, der sich als dein eigener tarnt."},
 {arab: "الْخَنَّاس", tr: "al-channās", wurzel: "ch-n-s", erkl: "„Der sich (immer wieder) Zurückziehende“ – dieselbe Wurzel wie al-chunnas in 81:15 (die zurückweichenden Planeten). Ibn ʿAbbās: Er hockt am Herzen; gedenkt der Mensch Allahs, zieht er sich zurück (chanasa) – wird der Mensch achtlos, flüstert er. Der Name verrät die Schwäche des Feindes: Dhikr vertreibt ihn sofort."},
 {arab: "يُوَسْوِسُ فِي صُدُور", tr: "yuwaswisu fī ṣudūr", wurzel: "ṣ-d-r", erkl: "„flüstert in die Brüste“ – ṣadr (Brust) ist im Koran der Vorhof des Herzens (qalb): Dort landen die Eingebungen, bevor das Herz sie annimmt oder verwirft. Deine Verantwortung beginnt nicht beim Gedanken, sondern bei seiner Annahme."},
 {arab: "مِنَ الْجِنَّةِ وَالنَّاس", tr: "mina l-dschinnati wa-n-nās", wurzel: "dsch-n-n / n-w-s", erkl: "„von den Dschinn und den Menschen“ – beide Quellen der Einflüsterung (vgl. 6:112: „Teufel von den Menschen und den Dschinn, die einander prunkende Worte eingeben“). Auch toxische Stimmen aus Fleisch und Blut fallen unter diese Sure."}
],
tafsir: [
 {vers: "Verse 1–3", text: "„Sag: Ich nehme Zuflucht beim Herrn der Menschen, dem König der Menschen, dem Gott der Menschen.“ – Dreimal „der Menschen“: Die Sure holt den Menschen bei seiner Schwäche ab und stellt ihm dreifach seinen Beschützer vor. Ibn Kathīr: Die drei Titel entsprechen den drei Bedürfnissen des Bedrohten – ein Erzieher, der dich kennt (rabb), ein König, dessen Befehl der Feind nicht brechen kann (malik), ein Gott, bei dem dein Herz ankommt (ilāh). As-Saʿdī: Zugleich sind sie Tauhīd-Lehre in Kurzform – Rubūbiyya, Mulk, Ulūhiyya."},
 {vers: "Verse 4–6", text: "„… vor dem Übel des Einflüsterers, des sich Zurückziehenden, der in die Brüste der Menschen einflüstert – von den Dschinn und den Menschen.“ – Al-Qurṭubī zum channās: Seine Taktik ist Geduld – er zieht sich zurück und kommt wieder, tausendmal; darum ist der Schutz auch kein Einmal-Akt, sondern Dauerpraxis (Dhikr, Gebet, die Schutzsuren morgens und abends). Die Sunna ergänzt das Innenleben-Protokoll: Lästige Glaubenszweifel? – „Das ist der klare Glaube“ (dass es dich stört!), sprich āmantu billāh und such Zuflucht (Sahih Muslim, Nr. 132–134). Waswās im Gebet? – Der Prophet ﷺ lehrte ʿUthmān ibn Abī l-ʿĀṣ: dreimal links ausspucken (trocken) und Zuflucht nehmen – „da ließ Allah es von mir weichen“ (Sahih Muslim, Nr. 2203). Und die Grundregel: „Allah hat meiner Umma vergeben, was ihre Seelen ihr einflüstern, solange sie nicht danach handelt oder spricht“ (Sahih al-Buchari, Nr. 5269; Sahih Muslim, Nr. 127) – der Gedanke allein ist keine Sünde; das nimmt der Waswasa ihren größten Hebel: die Panik."}
],
ahadith: [
 {text: "„Schaitan kommt zu einem von euch und sagt: Wer hat dies erschaffen, wer hat das erschaffen? – bis er sagt: Wer hat deinen Herrn erschaffen? Wenn es so weit kommt, dann soll er Zuflucht bei Allah suchen und (dem Gedanken) ein Ende machen.“", quelle: "Sahih al-Buchari, Nr. 3276; Sahih Muslim, Nr. 134"},
 {text: "Die Gefährten klagten über Einflüsterungen, die auszusprechen ihnen ungeheuerlich erschien. Der Prophet ﷺ: „Habt ihr das wirklich empfunden? Das ist der klare Glaube.“", quelle: "Sahih Muslim, Nr. 132"},
 {text: "„Allah hat meiner Umma vergeben, was ihre Seelen ihr einflüstern, solange sie nicht danach handelt oder davon spricht.“", quelle: "Sahih al-Buchari, Nr. 5269; Sahih Muslim, Nr. 127"}
],
hanafi: "Praktische hanafitische Regel gegen Waswasa in der ʿIbāda: Zweifel nach Abschluss einer Handlung werden ignoriert (Grundsatz: Gewissheit wird durch Zweifel nicht aufgehoben – al-yaqīn lā yazūl bi-sch-schakk, eine der Kernmaximen der hanafitischen Rechtsmaximen). Wer also NACH dem Wudū zweifelt, ob er einen Körperteil gewaschen hat, oder nach dem Gebet, ob es vier Rakʿa waren, ignoriert den Zweifel; nur wer noch mittendrin ist und erstmals zweifelt, baut auf dem Sicheren auf. Wiederholtes zwanghaftes Wiederholen von Wudū und Gebet ist genau das Werk des waswās und wird von den Fuqahāʾ ausdrücklich missbilligt – die Religion will Klarheit, nicht Skrupel-Schleifen.",
umsetzung: [
 "Nutze die channās-Schwäche: Sobald ein dunkler Gedanke kreist, sprich laut oder innerlich aʿūdhu billāhi mina sch-schaiṭāni r-radschīm und wechsle in Dhikr – der Name der Sure garantiert: Er weicht bei Gedenken.",
 "Wende die Vergebungs-Regel an: Aufdringliche Gedanken sind KEINE Sünde und kein Zeichen schwachen Glaubens – im Gegenteil (Muslim 132). Nicht erschrecken, nicht diskutieren, nicht vertiefen: registrieren, Zuflucht nehmen, weitermachen.",
 "Identifiziere deine menschlichen waswās-Quellen (114:6): Accounts, Gesprächskreise oder ‚Freunde', die systematisch Zweifel und Sünde einflüstern – Dosis reduzieren oder Abstand (hadschr dschamīl, Lektion 3).",
 "Bei Zweifel-Schleifen in Wudū/Gebet: hanafitische Maxime anwenden – nach Abschluss wird nicht wiederholt. Einmal entscheiden, nicht nachverhandeln: Genau das entzieht dem Einflüsterer das Spielfeld."
]
},

// ───────────────────────── Lektion 22: Al-Ichlāṣ ─────────────────────────
{
sure: 112, offb: 22, name: "Al-Ichlāṣ", arab: "سُورَةُ الْإِخْلَاصِ", de: "Die Aufrichtigkeit", verse: 4, ort: "Mekka",
zeit: "Frühmekkanisch – Antwort auf die Frage der Götzendiener: „Beschreibe uns deinen Herrn – von welcher Abstammung ist er?“",
kurz: "Vier Verse, die der Prophet ﷺ „ein Drittel des Korans“ nannte – weil der Koran aus Tauhīd, Gesetz und Berichten besteht und diese Sure den Tauhīd vollständig enthält. Die Götzendiener fragten: „Nenn uns den Stammbaum deines Herrn – ist er aus Gold? Wer erbt ihn?“ Die Antwort definiert Gott für immer: „Sag: Er ist Allah, Einer. Allah, aṣ-Ṣamad (der Absolute, auf Den alles angewiesen ist). Er hat nicht gezeugt und ist nicht gezeugt worden. Und niemand ist Ihm ebenbürtig.“ Jede falsche Gottesvorstellung der Religionsgeschichte – Götterfamilien, Gottessöhne, Naturgötter, der ‚liebe Opa im Himmel' – zerbricht an diesen vier Zeilen. Ein Gefährte, der die Sure in jedem Gebet las, „weil sie die Eigenschaft des Allerbarmers ist und ich liebe, sie zu lesen“, bekam die Antwort: „Allah liebt ihn.“",
schluessel: {arab: "قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ", ueb: "Sag: Er ist Allah, Einer. Allah, der Absolute (aṣ-Ṣamad).", ref: "112:1–2"},
kontext: ["Die Mekkaner dachten in Stammbäumen – auch über Götter: Sie nannten die Engel ‚Töchter Allahs', kannten Göttergenealogien ihrer Nachbarkulturen und fragten den Propheten ﷺ spöttisch nach der ‚Abstammung' seines Herrn (unsub lanā rabbak). Dazu kam die Umgebung: Perser (Dualismus), Christen (Sohn Gottes), Juden (ʿUzair-Vorstellung, vgl. 9:30). Die Sure antwortet allen gleichzeitig – in der Sprache der Verneinung alles Kreatürlichen (Bericht bei at-Tirmidhī, Nr. 3364, von Ubayy ibn Kaʿb: „Die Götzendiener sagten: Nenne uns die Abstammung deines Herrn – da sandte Allah herab: Qul huwa llāhu aḥad…“; hasan).",
"Der Name der Sure – Ichlāṣ, Aufrichtigkeit/Reinheit – ist doppeldeutig: Sie REINIGT die Gottesvorstellung von allem Falschen, und wer sie glaubt, reinigt seine Anbetung für den Einen. Sie kommt im Koran nie mit Namen vor, aber der Prophet ﷺ machte sie zum Dauerbaustein des Alltags: Fadschr-Sunna, Witr, Tawāf-Rakʿa, vor dem Schlafen, morgens und abends – du kennst die Stellen aus den Lektionen 8, 18, 20.",
"Zum „Drittel des Korans“: Die Gelehrten erklären es inhaltlich – die Botschaft des Korans ruht auf drei Säulen: Wissen über Allah (Tauhīd), Gesetz (Gebote/Verbote), Berichte (Propheten, Jenseits). Al-Ichlāṣ deckt die erste Säule komplett ab. Der Lohn des Rezitierens entspricht dem Drittel; er ERSETZT aber nicht den restlichen Koran – beides sagen die Fuqahāʾ klar."],
asbab: [
 {text: "Ubayy ibn Kaʿb: Die Götzendiener sagten: „Nenne uns die Abstammung (ansib) deines Herrn“ – daraufhin wurde die Sure herabgesandt.", quelle: "Sunan at-Tirmidhī, Nr. 3364; hasan (ähnlich bei Aḥmad)"}
],
begriffe: [
 {arab: "أَحَد", tr: "aḥad", wurzel: "ʾ-ḥ-d", erkl: "„Einer / ein Einziger“ – stärker als wāḥid (eins als Zahl): aḥad in dieser Verwendung bedeutet einzig in Seinem Wesen, unteilbar, ohne Zweiten seiner Art. Keine Zahl in einer Reihe, sondern eine eigene Kategorie."},
 {arab: "الصَّمَد", tr: "aṣ-ṣamad", wurzel: "ṣ-m-d", erkl: "Der, zu Dem alle sich in ihren Nöten wenden, während Er niemanden braucht – der Absolute, in Sich Vollkommene. Ibn ʿAbbās: der Herr, vollkommen in Herrschaft, Ehre, Macht, Wissen, Weisheit. Das Wort kommt im ganzen Koran nur hier vor – wie maßgeschneidert für diese eine Aussage."},
 {arab: "لَمْ يَلِدْ وَلَمْ يُولَدْ", tr: "lam yalid wa-lam yūlad", wurzel: "w-l-d", erkl: "„Er hat nicht gezeugt und wurde nicht gezeugt“ – die doppelte Absage an jede Genealogie Gottes: keine Söhne und Töchter (gegen Mekkas Engel-Töchter und das Konzept des Gottessohnes), kein Anfang aus einem Früheren. Wer zeugt, teilt sich; wer gezeugt wird, beginnt – beides widerspricht aḥad und ṣamad."},
 {arab: "كُفُوًا", tr: "kufuwan", wurzel: "k-f-ʾ", erkl: "„Ebenbürtig/gleichrangig“ – kufʾ ist der Gleichgestellte (das Wort kennt man aus dem Eherecht: kafāʾa, Ebenbürtigkeit). „Und niemand ist Ihm ebenbürtig“: kein Konkurrent, kein Partner, kein Gegenpol – auch kein ‚Teufel auf Augenhöhe'."}
],
tafsir: [
 {vers: "Verse 1–2", text: "„Sag: Er ist Allah, Einer. Allah, aṣ-Ṣamad.“ – Erst die Einzigkeit des Wesens (aḥad), dann die absolute Unabhängigkeit und Angewiesenheit aller auf Ihn (ṣamad). Ibn Kathīr: Die beiden Namen zusammen schließen jeden Mangel aus – Einer ohne Teilung, Absoluter ohne Bedürfnis. As-Saʿdī: ṣamad ist auch die Praxis-Brücke: WEIL alle Geschöpfe sich mit ihren Nöten an Ihn wenden, wende dich mit deinen Nöten direkt an Ihn – ohne Vermittler, ohne ‚Heilige', ohne Umwege. Die Sure, die Gottes Wesen beschreibt, ist damit zugleich die Begründung des direkten Duʿā."},
 {vers: "Verse 3–4", text: "„Er hat nicht gezeugt und ist nicht gezeugt worden, und niemand ist Ihm ebenbürtig.“ – Drei Verneinungen als Schutzwall: kein Nachkomme, kein Ursprung, kein Ebenbürtiger. Al-Qurṭubī: Damit sind alle historischen Irrtümer abgedeckt – Götterfamilien der Araber und Griechen, der Sohn-Gottes-Glaube, Dualismus (Licht/Finsternis als gleichstarke Mächte), und moderner Pantheismus (‚alles ist Gott'). Im Hadith Qudsi nimmt Allah die Zeugungs-Behauptung persönlich: „Der Sohn Ādams hat Mich der Lüge bezichtigt … und Mich geschmäht: seine Behauptung, Ich hätte einen Sohn – doch Ich bin der Eine, der Absolute; Ich habe nicht gezeugt und wurde nicht gezeugt, und niemand ist Mir ebenbürtig“ (Sahih al-Buchari, Nr. 4974). Deshalb wiegt die Sure ein Drittel: Wer sie versteht, hat die Gottesfrage – die wichtigste Frage des Lebens – endgültig beantwortet."}
],
ahadith: [
 {text: "„Bei Dem, in Dessen Hand meine Seele ist: Sie wiegt ein Drittel des Korans auf.“ – über Qul huwa llāhu aḥad.", quelle: "Sahih al-Buchari, Nr. 5013; vgl. Sahih Muslim, Nr. 811"},
 {text: "Ein Mann leitete das Gebet und schloss jede Rezitation mit Al-Ichlāṣ, „weil sie die Eigenschaft des Allerbarmers ist und ich liebe, sie zu lesen“. Der Prophet ﷺ: „Teilt ihm mit, dass Allah ihn liebt.“", quelle: "Sahih al-Buchari, Nr. 7375; Sahih Muslim, Nr. 813"},
 {text: "Hadith Qudsi: „Der Sohn Ādams bezichtigt Mich der Lüge … und schmäht Mich: seine Behauptung, Ich hätte einen Sohn …“", quelle: "Sahih al-Buchari, Nr. 4974"}
],
hanafi: null,
umsetzung: [
 "Lerne die Sure mit Verständnis neu: Du kannst sie längst auswendig – sprich sie eine Woche lang in jedem Gebet mit bewusster Bedeutung der vier Aussagen. Das ist der schnellste Weg zu mehr chuschūʿ.",
 "Nutze sie als Antwort-Werkzeug: Wenn dich jemand fragt „Wie stellt ihr Muslime euch Gott vor?“ – diese vier Verse sind die präziseste Antwort, die es gibt. Lerne sie auf Deutsch mitformulieren.",
 "Lebe ṣamad: Bevor du bei Menschen Hilfe suchst (erlaubt!), klopf ZUERST bei Dem an, auf Den alle angewiesen sind – mach das Duʿā vor dem Telefonat zur Gewohnheit.",
 "Komplettiere dein Tagesprogramm aus den Lektionen: Al-Ichlāṣ steht in Fadschr-Sunna (L18), Witr (L8), Schutzformel morgens/abends/nachts (L20) – damit rezitierst du das ‚Drittel des Korans' täglich mehrfach, mit Sunna-Beleg."
]
},

// ───────────────────────── Lektion 23: An-Nadschm ─────────────────────────
{
sure: 53, offb: 23, name: "An-Nadschm", arab: "سُورَةُ النَّجْمِ", de: "Der Stern", verse: 62, ort: "Mekka",
zeit: "Mittelmekkanisch – die erste Sure, die der Prophet ﷺ öffentlich vor den Quraisch rezitierte; am Ende warfen sich alle nieder",
kurz: "Mit dieser Sure betritt der Koran erstmals hörbar die Öffentlichkeit Mekkas – und sie beginnt mit einer Beglaubigung: „Beim Stern, wenn er sinkt! Euer Gefährte irrt nicht und lässt sich nicht täuschen, und er redet nicht aus Neigung – es ist nur eine Offenbarung, die eingegeben wird.“ Dann beschreibt sie, was der Prophet ﷺ wirklich sah: Dschibrīl in seiner wahren Gestalt am Horizont und bei der Himmelsreise am Lotusbaum der äußersten Grenze – „das Herz hat nicht gelogen, was es sah.“ Sie zerlegt die Götzinnen Mekkas (al-Lāt, al-ʿUzzā, Manāt) als bloße Namen, stellt die ewigen Grundsätze der früheren Offenbarungen vor („Keine Seele trägt die Last einer anderen; der Mensch bekommt nur, wofür er sich müht“) – und endet mit dem Befehl, der selbst die Spötter in die Knie zwang: „So werft euch vor Allah nieder und dient!“",
schluessel: {arab: "مَا كَذَبَ الْفُؤَادُ مَا رَأَىٰ", ueb: "Das Herz hat nicht gelogen, was es sah.", ref: "53:11"},
kontext: ["Ibn Masʿūd berichtet: An-Nadschm war die erste Sure, in der der Prophet ﷺ (öffentlich, vor den versammelten Quraisch) die Niederwerfung rezitierte – er warf sich nieder, und mit ihm warfen sich alle nieder, Muslime wie Götzendiener; nur ein alter Mann (Umayya ibn Chalaf) hob Kies an die Stirn und sagte: „Das genügt mir.“ Ibn Masʿūd fügt hinzu: Ich sah ihn später als Ungläubigen erschlagen (Sahih al-Buchari, Nr. 1067, 4863). Die Wucht der Sprache überwältigte selbst die Feinde – ein einmaliger Moment der frühen Daʿwa.",
"Die Sure antwortet auf den Kern-Vorwurf Mekkas: Muhammad ﷺ habe sich die Offenbarung ausgedacht oder sei getäuscht worden. Ihre Antwort ist die detaillierteste Beschreibung der Offenbarungserfahrung im ganzen Koran: die Begegnung mit Dschibrīl „am höchsten Horizont“, das Herannahen „auf zwei Bogenlängen oder näher“ (qāba qausaini au adnā), und die Vision bei der Himmelsreise an der sidrat al-muntahā. ʿĀʾischa und Ibn Masʿūd klären: Gesehen wurde Dschibrīl in seiner wahren Gestalt – nicht Allah selbst (Sahih Muslim, Nr. 174; Sahih al-Buchari, Nr. 4855–4857).",
"Zur berüchtigten „Kranich-Legende“ (ġarānīq): Spätere Berichte behaupten, Schaitan habe dem Propheten ﷺ Lobverse auf die Götzinnen untergeschoben, und DESHALB hätten sich die Quraisch mitniedergeworfen. Die Hadith-Kritiker (u. a. Ibn Chuzaima, al-Qāḍī ʿIyāḍ, al-Albānī in der Detailanalyse) verwerfen die Geschichte: keine einzige gesunde Kette, Widerspruch zum Koran selbst (53:3–4: „er redet nicht aus Neigung“; 22:52 garantiert die Reinigung der Offenbarung) und zum gesicherten Buchari-Bericht, der die Niederwerfung OHNE jede Kranich-Episode erklärt: Die Rezitation selbst überwältigte sie. Das musst du wissen, weil Islamkritik die Legende als „satanische Verse“ zitiert."],
asbab: [
 {text: "Ibn Masʿūd: Die erste Sure mit Sadschda, die der Prophet ﷺ (öffentlich) rezitierte; alle Anwesenden warfen sich mit ihm nieder bis auf einen Mann, der Kies an die Stirn hob.", quelle: "Sahih al-Buchari, Nr. 1067 und 4863"},
 {text: "Zu 53:32 („Wer Verzeihung übt …“) und den Grundsatz-Versen 36–41: Bezug auf einen, der erst gab und dann aus Angst vor ‚Verlust' aufhörte (nach verbreiteter Deutung al-Walīd ibn al-Muġīra, dem ein anderer anbot, seine ‚Sündenlast zu übernehmen') – Standardbericht der Tafsir-Werke zu 53:33–37.", quelle: "Tafsir aṭ-Ṭabarī / Ibn Kathīr zu 53:33 ff."}
],
begriffe: [
 {arab: "النَّجْم إِذَا هَوَىٰ", tr: "an-nadschm idhā hawā", wurzel: "n-dsch-m / h-w-y", erkl: "„Der Stern, wenn er sinkt/fällt“ – Schwur beim untergehenden Stern. Fein: hawā heißt auch „der Neigung folgen“ – und genau das wird zwei Verse später vom Propheten ﷺ verneint (mā yanṭiqu ʿani l-hawā): Der Stern folgt der Bahn seines Herrn, nicht seiner Laune – der Gesandte auch."},
 {arab: "مَا يَنطِقُ عَنِ الْهَوَىٰ", tr: "mā yanṭiqu ʿani l-hawā", wurzel: "n-ṭ-q / h-w-y", erkl: "„Er redet nicht aus (eigener) Neigung“ (53:3) – Grundsatzvers über die Sunna: Was der Prophet ﷺ an Dīn verkündet, ist Offenbarung (waḥy), nicht Meinung. Fundament dafür, warum Hadithe zweite Rechtsquelle sind."},
 {arab: "قَابَ قَوْسَيْن", tr: "qāba qausain", wurzel: "q-w-s", erkl: "„Zwei Bogenlängen (oder näher)“ – arabisches Maß äußerster Nähe. Beschreibt das Herannahen Dschibrīls an den Propheten ﷺ bei der ersten Begegnung in wahrer Gestalt (so Ibn Masʿūd und ʿĀʾischa; Sahih Muslim, Nr. 174)."},
 {arab: "سِدْرَة الْمُنتَهَىٰ", tr: "sidrat al-muntahā", wurzel: "s-d-r / n-h-y", erkl: "Der „Lotusbaum der äußersten Grenze“ beim siebten Himmel, bei dem der „Garten der Heimstatt“ liegt – Endpunkt dessen, was aufsteigt und absteigt. Dort sah der Prophet ﷺ in der Nacht der Himmelsreise Dschibrīl zum zweiten Mal in wahrer Gestalt (53:13–18)."},
 {arab: "اللَّات وَالْعُزَّىٰ وَمَنَاة", tr: "al-Lāt, al-ʿUzzā, Manāt", wurzel: "–", erkl: "Die drei Hauptgöttinnen der Hidschāz-Araber (Ṭāʾif, Nachla, Küste). 53:23: „Es sind nur Namen, die ihr euch ausgedacht habt, ihr und eure Väter; Allah hat dazu keine Ermächtigung herabgesandt.“ – Religionskritik in einem Satz: Ein Götze ist ein Name plus Gewohnheit, sonst nichts."},
 {arab: "أَزِفَتِ الْآزِفَة", tr: "azifati l-āzifa", wurzel: "ʾ-z-f", erkl: "„Die Nahe ist nahegerückt“ (53:57) – ein Name des Jüngsten Tages: die ohnehin Nahe. Kurz vor dem Schluss-Sadschda-Befehl: Der Ernst der Botschaft duldet kein Lachen und Wegwenden (53:59–61)."}
],
tafsir: [
 {vers: "Verse 1–18", text: "Beglaubigung des Gesandten und der Quelle: kein Irrtum, keine Täuschung, keine Eigenrede – „es ist nur eingegebene Offenbarung, gelehrt hat ihn der an Kräften Starke (Dschibrīl)“. Dann die zwei Visionen: am klaren Horizont (vgl. 81:23, Lektion 7) und an der sidrat al-muntahā, „als den Lotusbaum überdeckte, was (ihn) überdeckte – der Blick wich nicht ab und überschritt nicht das Maß. Er sah von den Zeichen seines Herrn die größten.“ Ibn Kathīr mit Ibn Masʿūd/ʿĀʾischa: Gesehen wurde Dschibrīl mit sechshundert Flügeln; „die größten Zeichen“, nicht Allah selbst – ʿĀʾischa: „Wer behauptet, Muhammad habe seinen Herrn gesehen, hat eine gewaltige Lüge über Allah gesagt“ (Sahih al-Buchari, Nr. 4855; die Gelehrten diskutieren nur über ein ‚Sehen mit dem Herzen'). Merke die Präzision von 53:17: Der Blick „wich nicht ab und überschritt nicht“ – Offenbarung ist das Gegenteil von Trance und Fantasie: kontrollierte, klare Wahrnehmung."},
 {vers: "Verse 19–30", text: "Die Abrechnung mit den Göttinnen: „Habt ihr al-Lāt und al-ʿUzzā gesehen und Manāt, die dritte? … Für euch die Söhne und für Ihn die Töchter? Das wäre eine ungerechte Verteilung!“ – Der Koran nimmt die Mekkaner bei ihrer eigenen Logik: Sie verachteten Töchter (Lektion 7!) und schrieben Allah ausgerechnet ‚Töchter' zu. Dann der Satz, der alle Götzen aller Zeiten trifft: „Es sind nur Namen, die ihr erfunden habt … Sie folgen nur der Vermutung und dem, wozu ihre Seelen neigen – wo ihnen doch von ihrem Herrn die Rechtleitung gekommen ist.“ As-Saʿdī: Vermutung (ẓann) und Neigung (hawā) sind bis heute die zwei Quellen jeder falschen Religion und Ideologie."},
 {vers: "Verse 31–41", text: "Mitten in der Sure ein Satz zur Selbsterziehung, den du für dein Tazkiya-Thema brauchst: „… Darum erklärt euch nicht selbst für rein (fa-lā tuzakkū anfusakum); Er weiß am besten, wer gottesfürchtig ist“ (53:32) – echte Tazkiya arbeitet an der Seele, falsche redet über die eigene Reinheit; aus diesem Vers leiteten die Gelehrten auch ab, Selbstlob zu meiden. Dann die „Blätter Mūsās und Ibrāhīms“ (vgl. Lektion 8!) mit den ewigen Grundsätzen: „Keine lasttragende (Seele) trägt die Last einer anderen. Und dass es für den Menschen nichts gibt außer dem, worum er sich müht, und dass sein Mühen gesehen werden wird, dann wird ihm dafür voll vergolten.“ – Absage an Erbsünde, Sippenhaft und Berechtigungs-Frömmigkeit in drei Zeilen."},
 {vers: "Verse 42–62", text: "Eine Kaskade der Macht Allahs: „dass ER lachen und weinen lässt, dass ER sterben lässt und lebendig macht … dass ER reich macht und genügsam“ – acht „dass Er“-Sätze, die alles Menschliche an Ihn zurückbinden. Dann die vernichteten Völker (ʿĀd, Ṯamūd, Nūḥs Volk, die umgestürzten Städte Lūts) als Beweis aus der Geschichte. Schluss: „Dies ist ein Warner von der Art der früheren Warner. Die Nahe ist nahegerückt … Wundert ihr euch über diese Rede, und lacht, und weint nicht? … So werft euch vor Allah nieder und dient!“ – Bei diesem Vers geschah die berühmte kollektive Niederwerfung. Al-Qurṭubī: Dass selbst Götzendiener niederfielen, zeigt die fitra – unter dem Spott liegt in jedem Menschen die Anlage, vor seinem Schöpfer zu fallen; die Daʿwa muss sie nur erreichen."}
],
ahadith: [
 {text: "Ibn Masʿūd: Der Prophet ﷺ rezitierte An-Nadschm und warf sich nieder, und alle mit ihm – bis auf den Mann mit dem Kies, „und ich sah ihn danach als Ungläubigen getötet“.", quelle: "Sahih al-Buchari, Nr. 1067; vgl. 4863"},
 {text: "ʿĀʾischa: „Wer dir erzählt, dass Muhammad ﷺ seinen Herrn gesehen hat, der hat gelogen … er sah Dschibrīl in seiner Gestalt, die Himmel bedeckend.“ / Ibn Masʿūd zu 53:18: „Er sah Dschibrīl mit sechshundert Flügeln.“", quelle: "Sahih al-Buchari, Nr. 4855; Sahih Muslim, Nr. 174"},
 {text: "„Keiner von euch soll sich selbst für rein erklären (lā yuzakkī aḥadukum nafsah)…“ – und zur Namensgebung: Der Prophet ﷺ änderte den Namen „Barra“ (die Fromme) in „Zainab“, damit niemand sage „sie ist rein“ – gelebte Anwendung von 53:32.", quelle: "Sahih Muslim, Nr. 2142"}
],
hanafi: "53:62 ist ein Sadschda-Vers – und zwar der erste, der öffentlich rezitiert wurde. Hanafitisch gilt (wie in Lektion 1): sadschdat at-tilāwa ist wādschib für den, der den Vers rezitiert oder (auch beiläufig) hört – mit Takbīr davor und danach, ohne Taslīm. Besonderheit dieser Sure aus der Sunna: Die Niederwerfung hier ist durch den Buchari-Bericht praktisch bezeugt – wenn du die Sure im Gebet oder außerhalb liest, vollziehst du exakt das nach, was in jener mekkanischen Stunde geschah.",
umsetzung: [
 "Lies An-Nadschm einmal laut (oder höre sie von einem Qāriʾ wie Minschāwī) und stell dir die Szene vor: die versammelten Quraisch, die wachsende Wucht, die Niederwerfung am Ende – und mach die Sadschda am Schluss bewusst mit (hanafitisch wādschib).",
 "Nimm 53:32 als Tazkiya-Regel: Arbeite an deiner Seele, aber sprich nicht über deine Frömmigkeit – kein ‚ich bin halt sehr spirituell'. Wer sich reinigt, muss sich nicht rein nennen.",
 "Lerne die Grundsätze 53:38–41 auswendig (keine Seele trägt fremde Last; dem Menschen nur sein Mühen; es wird gesehen; voll vergolten) – sie sind die Antwort auf Erbsünde, Sippenhaft und Fatalismus in einem.",
 "Für Gespräche: Kenne die Kranich-Legende und ihre Widerlegung (keine gesunde Kette, Widerspruch zu 53:3–4 und zum Buchari-Bericht) – damit dich ‚satanische Verse'-Polemik nie kalt erwischt."
]
},

// ───────────────────────── Lektion 24: ʿAbasa ─────────────────────────
{
sure: 80, offb: 24, name: "ʿAbasa", arab: "سُورَةُ عَبَسَ", de: "Er blickte düster", verse: 42, ort: "Mekka",
zeit: "Frühmekkanisch – die Korrektur des Propheten ﷺ wegen des blinden ʿAbdullāh ibn Umm Maktūm",
kurz: "Eine der erstaunlichsten Suren des Korans – weil sie den Propheten ﷺ selbst korrigiert und diese Korrektur für alle Zeiten verlesen wird. Der Prophet ﷺ war mitten im Gespräch mit den Großen der Quraisch und hoffte auf ihren Islam, der ganze Stadt den Durchbruch gebracht hätte. Da unterbrach ihn der blinde ʿAbdullāh ibn Umm Maktūm: „Lehre mich von dem, was Allah dich gelehrt hat!“ Der Prophet ﷺ blickte düster und wandte sich ab – kein Wort, nur ein Stirnrunzeln, das der Blinde nicht einmal sehen konnte. Darauf der Himmel: „Er blickte düster und kehrte sich ab, weil der Blinde zu ihm kam. Was lässt dich wissen – vielleicht wollte er sich läutern?“ Die Sure stellt die Maßstäbe der Daʿwa für immer richtig: Der aufrichtig Suchende hat Vorrang vor dem wichtigen Desinteressierten. Der Prophet ﷺ ehrte Ibn Umm Maktūm fortan, machte ihn zum Muezzin und ließ ihn bei Abwesenheit Medina verwalten.",
schluessel: {arab: "عَبَسَ وَتَوَلَّىٰ ۝ أَن جَاءَهُ الْأَعْمَىٰ", ueb: "Er blickte düster und kehrte sich ab, weil der Blinde zu ihm kam.", ref: "80:1–2"},
kontext: ["ʿĀʾischa berichtet den Anlass: Über Ibn Umm Maktūm wurde „ʿAbasa wa-tawallā“ herabgesandt – er kam zum Propheten ﷺ und sagte wiederholt: „O Gesandter Allahs, leite mich an!“, während bei ihm einer der Großen der Götzendiener war, dem er sich zuwandte in der Hoffnung auf dessen Islam (Sunan at-Tirmidhī, Nr. 3331; als Anlassbericht anerkannt; die Tafsir-Werke nennen al-Walīd, ʿUtba, Abū Dschahl u. a. als Gesprächspartner).",
"Versteh die Logik des Propheten ﷺ: Kein Hochmut – er kalkulierte Daʿwa-Wirkung. Ein einziger bekehrter Clanführer hätte Hunderte nachgezogen und die Verfolgung der Schwachen beendet; Ibn Umm Maktūm war ja schon Muslim und konnte warten. Menschlich völlig nachvollziehbar – und genau deshalb korrigiert die Offenbarung: Bei Allah zählt nicht die gesellschaftliche Hebelwirkung, sondern das suchende Herz. Die Ökonomie der Dunya (Reichweite, Multiplikatoren) ist nicht die Ökonomie des Himmels (Aufrichtigkeit).",
"Dass der Koran diese Rüge überhaupt enthält, ist zugleich der stärkste Echtheitsbeweis: Ein Mann, der sich Offenbarung ausdenkt, diktiert keine ewige Kritik an sich selbst. Und der Prophet ﷺ lebte die Korrektur radikal: Er begrüßte Ibn Umm Maktūm fortan mit den Worten „Willkommen dem, um dessentwillen mein Herr mich getadelt hat“, machte ihn zum zweiten Muezzin neben Bilāl (Sahih al-Buchari, Nr. 617) und setzte ihn mehrfach als Statthalter über Medina ein, wenn er auszog – den blinden Mann, über die Hauptstadt."],
asbab: [
 {text: "ʿĀʾischa: „Herabgesandt wurde ʿAbasa wa-tawallā über Ibn Umm Maktūm, den Blinden …“ – mit der Szene des unterbrochenen Gesprächs.", quelle: "Sunan at-Tirmidhī, Nr. 3331; ṣaḥīḥ nach al-Albānī (vgl. Muwaṭṭaʾ/weitere Ketten)"}
],
begriffe: [
 {arab: "عَبَسَ", tr: "ʿabasa", wurzel: "ʿ-b-s", erkl: "„Er runzelte die Stirn / blickte düster“ – dasselbe Verb beschreibt in 74:22 al-Walīds feindseliges Stirnrunzeln. Beachte die Schonung: Die Sure sagt „ER blickte“, nicht „DU blicktest“ – erst ab Vers 3 wird der Prophet ﷺ direkt und liebevoll angeredet. Getadelt wird die Tat, die Person wird geschont: Adab der Kritik, vom Himmel vorgemacht."},
 {arab: "الْأَعْمَىٰ", tr: "al-aʿmā", wurzel: "ʿ-m-y", erkl: "„Der Blinde“ – der Koran nennt Ibn Umm Maktūm bei seiner Schwäche, nicht beim Namen: Es geht ums Prinzip – JEDER Schwache, Unansehnliche, ‚Unwichtige' steht unter dem Schutz dieser Verse. Die eigentliche Blindheit der Szene lag bei den sehenden Großen, die die Wahrheit nicht sehen wollten."},
 {arab: "يَزَّكَّىٰ", tr: "yazzakkā", wurzel: "z-k-w", erkl: "„sich läutern“ (80:3) – wieder die Tazkiya-Wurzel (vgl. 87:14, 92:18): „Was lässt dich wissen – vielleicht wollte er sich läutern?“ Der Maßstab der Daʿwa ist das Läuterungs-Potenzial des Herzens, nicht der Status des Besitzers."},
 {arab: "تَصَدَّىٰ / تَلَهَّىٰ", tr: "taṣaddā / talahhā", wurzel: "ṣ-d-y / l-h-w", erkl: "80:6+10: „Dem, der sich unabhängig gibt, widmest du dich (taṣaddā) – und von dem, der eilig zu dir kommt und (Allah) fürchtet, lässt du dich ablenken (talahhā, vgl. alhākum in Lektion 16!).“ Zwei Verben, die jede Gemeinde prüfen: Wem widmen wir uns, von wem lassen wir uns ‚ablenken'?"},
 {arab: "سَفَرَة كِرَام بَرَرَة", tr: "safara kirām barara", wurzel: "s-f-r / k-r-m / b-r-r", erkl: "80:15–16: Die Offenbarung ist „in den Händen von Schreibern (Engeln) – edlen, frommen“. Daraus + 56:79 leiten die Fuqahāʾ die Ehrung des Mushaf ab. Der Kontext: Diese ehrwürdige Botschaft ist zu kostbar, um sie nach Menschen-Status zu dosieren."},
 {arab: "الصَّاخَّة", tr: "aṣ-ṣāchcha", wurzel: "ṣ-ch-ch", erkl: "„Die Ohrenbetäubende“ (80:33) – ein Name des Jüngsten Tags: der Schrei, der alles übertönt. Danach „flieht der Mensch vor seinem Bruder, seiner Mutter, seinem Vater, seiner Gefährtin und seinen Söhnen – jeder hat an jenem Tag genug mit sich selbst zu tun“ (34–37)."}
],
tafsir: [
 {vers: "Verse 1–10", text: "Die Rüge in zehn kurzen Versen, chirurgisch präzise: erst die distanzierte Beschreibung (er runzelte, er wandte sich ab), dann die Begründungsfrage („Was lässt dich wissen – vielleicht läutert er sich oder lässt sich erinnern, und die Erinnerung nützt ihm?“), dann die Gegenüberstellung: Dem Selbstgenügsamen (istaġnā – dieselbe Diagnose wie bei Abū Dschahl, 96:7!) widmest du dich, „und es ist nicht deine Verantwortung, wenn er sich nicht läutert“ – während der Eilende, Fürchtende kurz gehalten wird. Ibn Kathīr: Die Sure verbietet nicht die Daʿwa an die Mächtigen; sie verbietet, den Aufrichtigen dafür zurückzustellen. As-Saʿdī: Aus ihr leiteten die Gelehrten die Regel ab, dass der Lehrer den Fragenden nach Aufrichtigkeit, nicht nach Rang gewichtet – und dass Wissen eine Bringschuld gegenüber jedem Suchenden ist."},
 {vers: "Verse 11–16", text: "„Keineswegs! Es ist eine Erinnerung – wer will, gedenkt ihrer – auf geehrten Blättern, erhöht und rein, in den Händen von Schreibern, edlen, frommen.“ – Die Kamera schwenkt von der Straßenszene zur himmlischen Herkunft des Korans: Diese Botschaft hat einen Adel, der nicht von ihren Adressaten abhängt. Al-Qurṭubī: Wer sie dem ‚wichtigen' Publikum andienen will, verkennt ihren Rang – sie ehrt den, der sie annimmt, nicht umgekehrt."},
 {vers: "Verse 17–32", text: "„Verderben über den Menschen, wie undankbar er ist! Aus was hat Er ihn erschaffen? Aus einem Samentropfen … dann macht Er ihm den Weg leicht, dann lässt Er ihn sterben und bestattet ihn.“ Dann der Schwenk auf den gedeckten Tisch der Vorsehung: „Wir gießen das Wasser in Güssen, spalten die Erde in Spalten (vgl. falaq!) und lassen darin Korn wachsen, Reben und Gemüse, Oliven und Palmen, dichte Gärten, Früchte und Futter – als Nießbrauch für euch und euer Vieh.“ – As-Saʿdī: Zwischen den beiden Jenseits-Teilen steht diese Schöpfungs- und Versorgungsliste als Beweis: Der dich vom Tropfen bis zum Teller trägt, kann dich auch auferwecken – und verdient anderes als das Stirnrunzeln des Hochmuts."},
 {vers: "Verse 33–42", text: "Die ṣāchcha: Der Tag, an dem jeder vor den Nächsten flieht – „jeder von ihnen hat an jenem Tag eine Angelegenheit, die ihn (völlig) beschäftigt.“ Dann die zwei Gesichter: „strahlend, lachend, frohlockend“ – „und auf (anderen) Gesichtern Staub, bedeckt von Dunkelheit: Das sind die Ungläubigen, die Sittenlosen.“ – Der Bogen zur Eingangsszene schließt sich bitter-genau: Am Jüngsten Tag fragt niemand mehr, wer in Mekka ‚wichtig' war; die Gesichter sortieren sich nach Herzen. Der blinde Mann, dem das Stirnrunzeln galt, gehört zu den Strahlenden – er starb später als Träger des Banners in der Schlacht von Qādisiyya, den Koran im Herzen, den er damals eilig lernen wollte."}
],
ahadith: [
 {text: "ʿĀʾischa über den Offenbarungsanlass: Ibn Umm Maktūm kam zum Propheten ﷺ, während dieser mit einem der Großen der Götzendiener beschäftigt war – „leite mich an!“ – da kam die Sure herab.", quelle: "Sunan at-Tirmidhī, Nr. 3331; sahih nach al-Albānī"},
 {text: "Ibn Umm Maktūm war (neben Bilāl) Muezzin des Propheten ﷺ – „Bilāl ruft bei Nacht; esst und trinkt (im Ramadan), bis Ibn Umm Maktūm ruft“, denn er rief erst bei Fadschr.", quelle: "Sahih al-Buchari, Nr. 617; Sahih Muslim, Nr. 1092"},
 {text: "„Allah schaut nicht auf eure Gestalten und euren Besitz, sondern auf eure Herzen und eure Taten.“ – das Prinzip, das die Sure erzwingt.", quelle: "Sahih Muslim, Nr. 2564"},
 {text: "„Manch zerzauster, staubbedeckter, in Lumpen gekleideter Mensch, dem man keine Beachtung schenkt – würde er bei Allah schwören, Allah würde seinen Schwur wahr machen.“", quelle: "Sahih Muslim, Nr. 2622 (vgl. 2854 ähnlich)"}
],
hanafi: "Aus 80:15–16 zusammen mit 56:79 („das nur die Gereinigten berühren“) leiten die hanafitischen Fuqahāʾ ab: Das Berühren des Mushaf ohne Wudū ist nicht erlaubt (für den Ǧunub auch das Rezitieren) – die Schule ist hier strikter als manche moderne Erleichterung; eine Hülle/ein Träger macht das Tragen zulässig, und vom Smartphone-Display zu lesen ist nach verbreiteter zeitgenössischer hanafitischer Position ohne Wudū zulässig, weil der Bildschirm nicht der Mushaf selbst ist (Berühren der angezeigten Schrift bleibt zu vermeiden). Praktisch: Für dein tägliches Koranlesen mit Mushaf – Wudū als Standard; unterwegs per App bist du flexibel.",
umsetzung: [
 "Übernimm den ʿAbasa-Maßstab: Wenn in Moschee, Unterricht oder Familie gleichzeitig der ‚Wichtige' und der aufrichtig Fragende deine Aufmerksamkeit wollen – der Fragende zuerst. Besonders: Kinder, Neulinge, Menschen mit Behinderung.",
 "Prüf deine Daʿwa-Ökonomie: Richtest du Inhalte/Energie nach Reichweite und Status aus oder nach Aufrichtigkeit der Empfänger? Die Sure erlaubt Strategie – aber nie auf Kosten eines suchenden Herzens.",
 "Lerne den Adab der Korrektur aus Vers 1–2: Kritisiere die Tat in der dritten Person, schone die Person, sprich sie danach liebevoll direkt an – so hat Allah Seinen eigenen Geliebten korrigiert.",
 "Wenn du korrigiert wirst (von Eltern, Lehrern, Geschwistern im Dīn): Reagiere wie der Prophet ﷺ – er versteckte die Rüge nicht, er rezitierte sie öffentlich und EHRTE den Anlass („Willkommen dem, um dessentwillen mein Herr mich getadelt hat“). Korrektur annehmen ist Prophetensunna."
]
}
];
